function toast(text){const el=$('#toast');el.textContent=text;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2600)}
function nav(){const allowed=!!state.session&&['operator','admin'].includes(state.profile?.role);const items=allowed?[['dashboard','Dashboard'],['people','Indivíduos'],['vehicles','Veículos'],...(state.profile?.role==='admin'?[['team','Usuários'],['history','Histórico']]:[])]:[];$('#bottomNav').hidden=!allowed;$('#sideNav').hidden=!allowed;$('#menuToggle').hidden=!allowed;$('#drawer').hidden=!allowed;if(!allowed)$('#drawer').classList.remove('open');document.body.classList.toggle('auth-mode',!allowed);const html=items.map(([id,name])=>'<button class="nav-item '+(state.page===id?'active':'')+'" data-page="'+id+'"><span class="nav-icon">'+ (id==='people'?personIcon():id==='vehicles'?carIcon().replace('car-icon','car-icon menu-svg'):icon[id]) +'</span><span>'+name+'</span></button>').join('');$('#sideNav').innerHTML=html;$('#bottomNav').innerHTML=html;$('#pageTitle').textContent=state.selected?(state.page==='people'?'Detalhes do indivíduo':'Detalhes do veículo'):label[state.page]||'Indivíduos';$('#signOut').hidden=!state.session}
function captureAppView(){return{page:state.page,selected:state.selected,query:state.query,searchInput:state.searchInput,listPage:state.listPage,letter:state.letter}}
function pushAppRoute(){state.routeStack.push(captureAppView());history.pushState({cadastroRoute:true},'',location.href)}
