function closeDrawer(){const drawer=$('#drawer');drawer?.classList.remove('open');if(state.drawerHistory){state.drawerHistory=false;state.ignoreNavigationPop=true;history.back()}}
async function restoreAppView(view){state.page=view.page;state.selected=view.selected;state.query=view.query||'';state.searchInput=view.searchInput||'';state.listPage=view.listPage||0;state.letter=view.letter||'all';saveLastView();if(state.selected&&state.page==='people')await openPerson(state.selected,true);else if(state.selected&&state.page==='vehicles')await openVehicle(state.selected,true);else await loadPage()}
async function handleAppPopState(){if(state.ignoreNavigationPop){state.ignoreNavigationPop=false;return}if(state.drawerHistory){state.drawerHistory=false;$('#drawer')?.classList.remove('open');return}if(state.modalHistory){state.modalHistory=false;const dialog=$('#recordDialog')?.open?$('#recordDialog'):$('#photoDialog');if(dialog?.open){state.closingModalFromBack=true;dialog.close();state.closingModalFromBack=false}return}const previous=state.routeStack.pop();if(previous){await restoreAppView(previous);return}if(state.selected){state.selected=null;await loadPage();return}if(state.page!=='dashboard'){state.page='dashboard';state.query='';state.searchInput='';await loadPage()}}
window.addEventListener('popstate',()=>{void handleAppPopState()});
for(const modal of [$('#recordDialog'),$('#photoDialog')])modal?.addEventListener('close',()=>{if(state.modalHistory&&!state.closingModalFromBack){state.modalHistory=false;state.ignoreNavigationPop=true;history.back()}});
function lastViewKey(userId){return 'cadastro:last-view:'+userId}
function saveLastView(){const userId=state.session?.user?.id;if(!userId)return;try{localStorage.setItem(lastViewKey(userId),JSON.stringify({page:state.page,selected:state.selected,listPage:state.listPage,letter:state.letter}))}catch{}}
function getLastView(userId){try{const value=JSON.parse(localStorage.getItem(lastViewKey(userId))||'null');if(!value||!['dashboard','people','vehicles','team','history'].includes(value.page))return null;if(['team','history'].includes(value.page)&&!isAdmin())return null;return {page:value.page,selected:typeof value.selected==='string'?value.selected:null,listPage:Math.max(0,Number(value.listPage)||0),letter:typeof value.letter==='string'?value.letter:'all'}}catch{return null}}
function frame(content){$('#mainContent').innerHTML=content;$('#mainContent').focus({preventScroll:true});}
function authPage(error=''){document.body.classList.add('auth-mode');$('#drawer').hidden=true;$('#drawer').classList.remove('open');frame('<div class="auth-wrap"><section class="auth-card"><div class="auth-brand"><div class="brand-mark auth-mark"><svg viewBox="0 0 64 64" aria-hidden="true"><path d="M32 6 51 13v14c0 13-7.7 22.8-19 29C20.7 49.8 13 40 13 27V13L32 6Z" fill="none" stroke="currentColor" stroke-width="3" stroke-linejoin="round"/><circle cx="32" cy="24" r="6" fill="none" stroke="currentColor" stroke-width="3"/><path d="M21 43c1.5-6.5 5-9.5 11-9.5S41.5 36.5 43 43" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round"/></svg></div><div class="auth-brand-copy"><h1>Cadastro Criminal</h1><p>Indivíduos e veículos</p></div></div><p class="auth-caption">Entre com seu e-mail e senha ou clique em “Continuar com Google” para acessar o banco de dados.</p>'+(error?'<div class="error-box">'+esc(error)+'</div>':'')+'<form id="loginForm" class="auth-form"><div class="field"><label for="email">E-mail</label><input id="email" name="email" type="email" autocomplete="username" required></div><div class="field"><label for="password">Senha</label><input id="password" name="password" type="password" autocomplete="current-password" required></div><button class="button auth-submit" type="submit">Entrar</button></form><button class="button secondary auth-submit" id="googleLogin" type="button">Continuar com Google</button><button class="text-button" id="forgotPassword">Esqueci minha senha</button><p class="auth-foot">Acesso por convite. Se ainda não recebeu um, fale com o administrador. Para instalar no celular, use o menu do navegador e escolha “Adicionar à tela inicial”.</p></section></div>');$('#loginForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);const {error}=await state.client.auth.signInWithPassword({email:f.get('email'),password:f.get('password')});if(error)authPage('E-mail ou senha incorretos.');};$('#googleLogin').onclick=async()=>{const {error}=await state.client.auth.signInWithOAuth({provider:'google',options:{redirectTo:location.origin+location.pathname}});if(error)authPage('Não foi possível iniciar o login Google: '+msg(error))};$('#forgotPassword').onclick=async()=>{const email=$('#email').value.trim();if(!email){authPage('Digite seu e-mail para receber o link de redefinição.');$('#email')?.focus();return}const {error}=await state.client.auth.resetPasswordForEmail(email,{redirectTo:location.origin+location.pathname});toast(error?msg(error):'Se a conta existir, enviaremos o link para redefinir a senha.')}}
function setupPasswordPage(){frame('<div class="auth-wrap"><section class="auth-card"><div class="brand-mark auth-mark"><img src="'+appIconUrl+'" alt=""></div><h1>Defina sua senha</h1><p class="auth-caption">Escolha uma senha para concluir seu primeiro acesso.</p><form id="newPasswordForm" class="auth-form"><div class="field"><label for="newPassword">Nova senha</label><input id="newPassword" name="password" type="password" minlength="12" autocomplete="new-password" required><small>Use pelo menos 12 caracteres.</small></div><div class="field"><label for="confirmPassword">Confirme a senha</label><input id="confirmPassword" name="confirm" type="password" minlength="12" autocomplete="new-password" required></div><button class="button auth-submit">Salvar senha</button></form></section></div>');$('#newPasswordForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);if(f.get('password')!==f.get('confirm')){toast('As senhas não coincidem.');return}const {data,error}=await state.client.auth.updateUser({password:f.get('password'),data:{must_change_password:false}});if(error){toast(msg(error));return}state.passwordSetup=false;if(data?.user&&state.session)state.session={...state.session,user:data.user};history.replaceState(null,'',location.pathname);toast('Senha definida. Aguardando liberação do administrador.');await loadUser(state.session)}}
function loadingPage(text='Carregando…'){frame('<div class="empty loading">'+esc(text)+'</div>')}
async function loadUser(session){const oldUserId=state.session?.user?.id;if(oldUserId&&oldUserId!==session?.user?.id)await clearPhotoCache(oldUserId);state.session=session;if(session?.user?.user_metadata?.must_change_password)state.passwordSetup=true;nav();if(!session){state.profile=null;nav();authPage();return}loadingPage('Validando acesso…');const {data,error}=await state.client.from('profiles').select('id,email,display_name,role').eq('id',session.user.id).single();if(error){state.profile=null;authPage('Não foi possível consultar seu perfil. Confirme se a instalação do banco foi concluída.');return}state.profile=data;if(state.passwordSetup){setupPasswordPage();return}nav();if(data.role==='pending'||data.role==='disabled'){frame('<div class="auth-wrap"><section class="auth-card"><div class="brand-mark auth-mark"><img src="'+appIconUrl+'" alt=""></div><h1>Acesso pendente</h1><p class="auth-caption">Sua conta foi criada. O administrador precisa liberar o acesso antes de você consultar cadastros.</p><button class="button auth-submit" id="pendingSignOut">Sair</button></section></div>');$('#pendingSignOut').onclick=()=>state.client.auth.signOut();return}const lastView=getLastView(session.user.id);state.page=lastView?.page||'dashboard';state.selected=null;if(lastView){state.listPage=lastView.listPage;state.letter=lastView.letter}if(lastView?.selected&&lastView.page==='people'){await openPerson(lastView.selected);return}if(lastView?.selected&&lastView.page==='vehicles'){await openVehicle(lastView.selected);return}await loadPage()}
function isAdmin(){return state.profile?.role==='admin'}
function openPhotoDb(){if(!('indexedDB' in window))return Promise.resolve(null);if(!photoDbPromise)photoDbPromise=new Promise(resolve=>{const request=indexedDB.open('cadastro-photo-cache-v1',1);request.onupgradeneeded=()=>{const db=request.result;if(!db.objectStoreNames.contains('photos'))db.createObjectStore('photos',{keyPath:'key'})};request.onsuccess=()=>resolve(request.result);request.onerror=()=>resolve(null)});return photoDbPromise}
async function readCachedPhoto(key){const db=await openPhotoDb();if(!db)return null;return new Promise(resolve=>{try{const request=db.transaction('photos').objectStore('photos').get(key);request.onsuccess=()=>resolve(request.result?.blob||null);request.onerror=()=>resolve(null)}catch{resolve(null)}})}
async function writeCachedPhoto(key,blob){const db=await openPhotoDb();if(!db)return;await new Promise(resolve=>{try{const request=db.transaction('photos','readwrite').objectStore('photos').put({key,blob,updated_at:Date.now()});request.onsuccess=request.onerror=()=>resolve()}catch{resolve()}})}
async function clearPhotoCache(userId){const prefix=String(userId)+':';for(const [key,url] of photoUrls){if(key.startsWith(prefix)){URL.revokeObjectURL(url);photoUrls.delete(key)}}const db=await openPhotoDb();if(!db)return;await new Promise(resolve=>{try{const tx=db.transaction('photos','readwrite'),store=tx.objectStore('photos'),request=store.getAllKeys();request.onsuccess=()=>{for(const key of request.result)if(String(key).startsWith(prefix))store.delete(key)};tx.oncomplete=tx.onerror=()=>resolve()}catch{resolve()}})}
function externalPhotoUrl(path){try{const url=new URL(String(path||''));if(url.protocol!=='https:')return '';if(url.hostname==='drive.google.com'){const id=url.searchParams.get('id')||url.pathname.match(/\/d\/([^/]+)/)?.[1];return id?'https://drive.google.com/thumbnail?id='+encodeURIComponent(id)+'&sz=w1200':''}if(url.hostname==='storage.googleapis.com'||url.hostname.endsWith('.googleusercontent.com'))return url.href;return ''}catch{return ''}}
async function galleryPhotoUrl(path){if(!path)return '';const external=externalPhotoUrl(path);if(external)return external;const userId=state.session?.user?.id;if(!userId)return '';const key=userId+':'+path;if(photoUrls.has(key))return photoUrls.get(key);const cached=await readCachedPhoto(key);if(cached){const objectUrl=URL.createObjectURL(cached);photoUrls.set(key,objectUrl);return objectUrl}const {data,error}=await state.client.storage.from('people-photos').createSignedUrl(path,3600);return error?'':data?.signedUrl||''}
async function signedPhoto(path){if(!path)return '';const external=externalPhotoUrl(path);if(external)return external;const userId=state.session?.user?.id;if(!userId)return '';const key=userId+':'+path;if(photoUrls.has(key))return photoUrls.get(key);const cached=await readCachedPhoto(key);if(cached){const url=URL.createObjectURL(cached);photoUrls.set(key,url);return url}const {data,error}=await state.client.storage.from('people-photos').createSignedUrl(path,3600);if(error||!data?.signedUrl)return '';try{const response=await fetch(data.signedUrl,{mode:'cors'});if(response.ok){const blob=await response.blob();await writeCachedPhoto(key,blob);const url=URL.createObjectURL(blob);photoUrls.set(key,url);return url}}catch{}return data.signedUrl}
async function loadAllActive(table,orderColumn){const rows=[];for(let start=0;;start+=1000){const {data,error}=await state.client.from(table).select('*').is('archived_at',null).order(orderColumn).order('id').range(start,start+999);if(error)throw error;const batch=data||[];rows.push(...batch);if(batch.length<1000)return rows}}
async function loadPagedActive(entity,orderColumn){const fetchPage=()=>{let query=state.client.from(entity).select('*',{count:'exact'}).is('archived_at',null);if(entity==='people'&&state.letter!=='all'){const accents={A:['A','Á','À','Â','Ã','Ä'],C:['C','Ç'],E:['E','É','È','Ê','Ë'],I:['I','Í','Ì','Î','Ï'],O:['O','Ó','Ò','Ô','Õ','Ö'],U:['U','Ú','Ù','Û','Ü']};const prefixes=accents[state.letter]||[state.letter];query=query.or(prefixes.map(letter=>'full_name.ilike.'+letter+'%').join(','))}return query.order(orderColumn).order('id')};let result=await fetchPage().range(state.listPage*state.listPageSize,(state.listPage+1)*state.listPageSize-1);if(result.error)throw result.error;const count=result.count||0,pages=Math.max(1,Math.ceil(count/state.listPageSize));if(state.listPage>=pages){state.listPage=pages-1;result=await fetchPage().range(state.listPage*state.listPageSize,(state.listPage+1)*state.listPageSize-1);if(result.error)throw result.error}state.listTotal=result.count||0;state.serverPaged=true;return result.data||[]}
async function loadRecords(requestId=state.searchRequest){state.serverPaged=false;state.listTotal=0;const query=state.query.trim();if(isUsefulSearch(query)){if(state.page==='people'){const [people,vehicles]=await Promise.all([state.client.rpc('search_people',{search_term:query,result_limit:100}),state.client.rpc('search_vehicles',{search_term:query,result_limit:100})]);if(requestId!==state.searchRequest)return;if(people.error)throw people.error;if(vehicles.error)throw vehicles.error;state.people=people.data||[];state.vehicles=vehicles.data||[]}else if(state.page==='vehicles'){const [vehicles,people]=await Promise.all([state.client.rpc('search_vehicles',{search_term:query,result_limit:100}),state.client.rpc('search_people',{search_term:query,result_limit:100})]);if(requestId!==state.searchRequest)return;if(vehicles.error)throw vehicles.error;if(people.error)throw people.error;state.vehicles=vehicles.data||[];state.people=people.data||[]}return}if(query){state.people=[];state.vehicles=[];return}if(state.page==='people'){state.people=await loadPagedActive('people','full_name');if(requestId!==state.searchRequest)return;state.vehicles=[]}else if(state.page==='vehicles'){state.vehicles=await loadPagedActive('vehicles','plate');if(requestId!==state.searchRequest)return;state.people=[]}}async function loadPage(){if(!state.session){authPage();return}if(state.page==='team'&&!isAdmin())state.page='people';if(state.page==='history'&&!isAdmin())state.page='dashboard';state.selected=null;saveLastView();nav();loadingPage();try{if(state.page==='dashboard')await renderDashboard();else if(['people','vehicles'].includes(state.page)){await loadRecords();await renderRecords()}else if(state.page==='team')await renderTeam();else if(state.page==='history')await renderHistory()}catch(e){frame('<div class="error-box">'+esc(msg(e))+'</div>')}}
async function galleryPhotos(entity,record){const photos=[];const {data,error}=await state.client.from('record_photos').select('id,photo_path,is_cover,crop_position,created_at').eq('entity',entity).eq('entity_id',record.id).order('created_at',{ascending:true});if(error)console.warn('A galeria unificada não está disponível; vou tentar as fotos antigas.',error);else photos.push(...(data||[]));const legacyTable=entity==='people'?'person_photos':'vehicle_photos',foreignKey=entity==='people'?'person_id':'vehicle_id';let legacy=[];for(const [columns,sort] of [['photo_path,created_at,sort_order',['sort_order','created_at']],['photo_path,created_at',['created_at']],['photo_path',[]]]){let query=state.client.from(legacyTable).select(columns).eq(foreignKey,record.id);for(const column of sort)query=query.order(column,{ascending:true});const result=await query;if(!result.error){legacy=result.data||[];break}}const pathKey=path=>externalPhotoUrl(path)||String(path||'');for(const old of legacy){if(!old.photo_path||photos.some(photo=>pathKey(photo.photo_path)===pathKey(old.photo_path)))continue;const isCover=!photos.some(photo=>photo.is_cover)&&(record.photo_path?pathKey(old.photo_path)===pathKey(record.photo_path):!photos.length);photos.push({id:null,photo_path:old.photo_path,is_cover:isCover,crop_position:'50% 50%',created_at:old.created_at})}if(record.photo_path&&!photos.some(photo=>pathKey(photo.photo_path)===pathKey(record.photo_path)))photos.unshift({id:null,photo_path:record.photo_path,is_cover:!photos.some(photo=>photo.is_cover),crop_position:record.photo_position||'50% 50%'});const seenPaths=new Set(),uniquePhotos=orderedPhotos(photos).filter(photo=>{const key=pathKey(photo.photo_path);if(!key||seenPaths.has(key))return false;seenPaths.add(key);return true});return await Promise.all(uniquePhotos.map(async photo=>({...photo,url:await signedPhoto(photo.photo_path)})))}
function parsePhotoCrop(value,portrait=false){const parts=String(value||'').match(/^(\d{1,3}(?:\.\d+)?)%\s+(\d{1,3}(?:\.\d+)?)%(?:\|z=([\d.]+))?$/);if(!parts)return{position:portrait?'50% 20%':'50% 50%',scale:1};let x=Math.max(0,Math.min(100,Number(parts[1]))),y=Math.max(0,Math.min(100,Number(parts[2])));if(portrait&&x===50&&y===50)y=20;return{position:x+'% '+y+'%',scale:Math.max(1,Math.min(3,Number(parts[3]||1)))}}
function photoPosition(value,portrait=false){return parsePhotoCrop(value,portrait).position}
function photoScale(value){return parsePhotoCrop(value).scale}
function photoStyle(value,portrait=false){return'object-position:'+photoPosition(value,portrait)+';transform:scale('+photoScale(value)+')'}

function orderedPhotos(photos){return [...photos].sort((a,b)=>Number(Boolean(b.is_cover))-Number(Boolean(a.is_cover)))}
async function galleryPhotosForRecords(entity,records){if(!records.length)return;const ids=records.map(record=>record.id),byId=new Map(ids.map(id=>[id,[]]));const {data,error}=await state.client.from('record_photos').select('id,entity_id,photo_path,is_cover,crop_position,created_at').eq('entity',entity).in('entity_id',ids).order('created_at',{ascending:true});if(error)console.warn('A galeria unificada não está disponível na listagem.',error);else for(const photo of data||[])byId.get(photo.entity_id)?.push(photo);const legacyTable=entity==='people'?'person_photos':'vehicle_photos',foreignKey=entity==='people'?'person_id':'vehicle_id';let legacy=[];for(const [columns,sort] of [['photo_path,created_at,sort_order',['sort_order','created_at']],['photo_path,created_at',['created_at']],['photo_path',[]]]){let query=state.client.from(legacyTable).select(columns).in(foreignKey,ids);for(const column of sort)query=query.order(column,{ascending:true});const result=await query;if(!result.error){legacy=result.data||[];break}}const key=path=>externalPhotoUrl(path)||String(path||'');for(const record of records){const photos=byId.get(record.id)||[];for(const old of legacy.filter(photo=>photo[foreignKey]===record.id)){if(!old.photo_path||photos.some(photo=>key(photo.photo_path)===key(old.photo_path)))continue;photos.push({id:null,photo_path:old.photo_path,is_cover:false,crop_position:'50% 50%',created_at:old.created_at})}if(record.photo_path&&!photos.some(photo=>key(photo.photo_path)===key(record.photo_path)))photos.unshift({id:null,photo_path:record.photo_path,is_cover:!photos.some(photo=>photo.is_cover),crop_position:record.photo_position||'50% 50%'});const ordered=orderedPhotos(photos);record.photo_count=ordered.length;record.photos=await Promise.all(ordered.slice(0,5).map(async photo=>({...photo,url:await galleryPhotoUrl(photo.photo_path)})))}}
function carouselMarkup(photos,{size='detail',label='Foto',portrait=false,zoom=true}={}){if(!photos?.length)return '<div class="photo-empty">Nenhuma foto cadastrada.</div>';const cover=photos.findIndex(photo=>photo.is_cover),selected=cover>=0?cover:0,active=photos[selected],id='gallery-'+Math.random().toString(36).slice(2);return '<section class="record-gallery '+(size==='card'?'record-gallery-card':'record-gallery-detail')+(portrait?' portrait-gallery':'')+'" data-photo-carousel="'+id+'" data-current-photo="'+selected+'"><div class="carousel-stage"><button type="button" class="carousel-main"'+(zoom?' data-photo-zoom="'+esc(active.url)+'"':'')+' aria-label="'+(zoom?'Ampliar ':'Ver ')+label+' '+(selected+1)+'"><img data-carousel-main src="'+esc(active.url)+'" alt="'+label+' '+(selected+1)+'" '+(size==='card'?'loading="lazy" decoding="async" ':'')+'style="'+esc(photoStyle(active.crop_position,portrait))+'"><span class="carousel-count" data-carousel-count>'+(selected+1)+' / '+photos.length+'</span></button>'+(photos.length>1?'<button type="button" class="carousel-arrow carousel-previous" data-carousel-step="-1" aria-label="Foto anterior">‹</button><button type="button" class="carousel-arrow carousel-next" data-carousel-step="1" aria-label="Próxima foto">›</button>':'')+'</div>'+(photos.length>1?'<div class="carousel-thumbnails" aria-label="Galeria de fotos">'+photos.map((photo,index)=>'<button type="button" class="carousel-thumb '+(index===selected?'active':'')+'" data-carousel-photo="'+index+'" data-photo-url="'+esc(photo.url)+'" data-photo-position="'+esc(photo.crop_position||'50% 50%')+'" aria-label="Mostrar '+label+' '+(index+1)+'"><img src="'+esc(photo.url)+'" alt="Miniatura '+(index+1)+'" loading="lazy"><span>'+(photo.is_cover?'Capa':String(index+1))+'</span></button>').join('')+'</div>':'')+'</section>'}
function galleryMarkup(photos,portrait=false){return carouselMarkup(orderedPhotos(photos),{portrait,label:portrait?'Foto do indivíduo':'Foto'})}
function editPhotoGalleryMarkup(photos){if(!photos.length)return '<p class="muted">Este cadastro ainda não possui fotos.</p>';return '<div class="edit-photo-gallery">'+photos.map((photo,index)=>'<article class="edit-photo-card photo-item" data-edit-photo-card="'+esc(photo.id||'')+'" data-photo-crop-position="'+esc(photo.crop_position||'50% 50%')+'"><div class="edit-photo-image-wrap"><button type="button" class="photo-zoom edit-photo-image" data-photo-zoom="'+esc(photo.url)+'" aria-label="Ampliar foto atual '+(index+1)+'"><img src="'+esc(photo.url)+'" alt="Foto atual '+(index+1)+'" style="'+esc(photoStyle(photo.crop_position))+'" loading="lazy"></button>'+(isAdmin()&&photo.id?'<button type="button" class="crop-inline-open" data-photo-crop-open="'+esc(photo.id)+'" aria-label="Ajustar enquadramento diretamente na foto" title="Ajustar diretamente na foto">✥</button><div class="crop-inline-controls" data-crop-inline-controls hidden><span>Arraste ou use pinça para enquadrar</span><button type="button" class="button secondary small" data-crop-inline-cancel>Cancelar</button><button type="button" class="button small" data-crop-inline-save>Salvar ajuste</button></div>':'')+'</div><div class="edit-photo-actions">'+(isAdmin()?'<label><input type="radio" name="editCoverPhoto" value="'+index+'" data-edit-cover-path="'+esc(photo.photo_path)+'" '+(photo.is_cover?'checked':'')+'> Capa</label><label class="delete-photo-choice"><input type="checkbox" data-edit-delete-photo="'+esc(photo.id||'legacy')+'" data-delete-path="'+esc(photo.photo_path)+'"> Excluir</label>':(photo.is_cover?'<span class="muted">Capa</span>':''))+'</div></article>').join('')+'</div>'}

function selectCarouselPhoto(carousel,index){const thumbs=[...carousel.querySelectorAll('[data-carousel-photo]')];if(!thumbs.length)return;index=(index+thumbs.length)%thumbs.length;const thumb=thumbs[index],main=carousel.querySelector('[data-carousel-main]'),zoom=carousel.querySelector('[data-photo-zoom]');main.src=thumb.dataset.photoUrl;main.alt='Foto '+(index+1);main.style.objectPosition=photoPosition(thumb.dataset.photoPosition||'50% 50%');main.style.transform='scale('+photoScale(thumb.dataset.photoPosition||'50% 50%')+')';if(zoom)zoom.dataset.photoZoom=thumb.dataset.photoUrl;carousel.dataset.currentPhoto=String(index);carousel.querySelector('[data-carousel-count]').textContent=(index+1)+' / '+thumbs.length;thumbs.forEach((item,i)=>item.classList.toggle('active',i===index));thumb.scrollIntoView({block:'nearest',inline:'nearest',behavior:'smooth'})}
function wireCarousels(){document.querySelectorAll('[data-photo-carousel]').forEach(carousel=>{if(carousel.dataset.swipeReady)return;carousel.dataset.swipeReady='true';let start=0;const stage=carousel.querySelector('.carousel-stage');stage?.addEventListener('touchstart',event=>{start=event.changedTouches[0].clientX},{passive:true});stage?.addEventListener('touchend',event=>{const delta=event.changedTouches[0].clientX-start;if(Math.abs(delta)>45)selectCarouselPhoto(carousel,Number(carousel.dataset.currentPhoto||0)+(delta<0?1:-1))},{passive:true})})}
async function renderDashboard(){const [{count:peopleCount,error:peopleError},{count:vehicleCount,error:vehicleError}]=await Promise.all([state.client.from('people').select('id',{count:'exact',head:true}).is('archived_at',null),state.client.from('vehicles').select('id',{count:'exact',head:true}).is('archived_at',null)]);if(peopleError)throw peopleError;if(vehicleError)throw vehicleError;frame('<section class="dashboard-intro"><h1>Dashboard</h1><p>Resumo dos cadastros ativos.</p></section><div class="dashboard-cards"><button class="dashboard-card" data-page="people"><span class="dashboard-icon">'+personIcon()+'</span><span class="dashboard-label">Indivíduos cadastrados</span><strong>'+Number(peopleCount||0).toLocaleString('pt-BR')+'</strong><span class="dashboard-link">Abrir cadastros →</span></button><button class="dashboard-card" data-page="vehicles"><span class="dashboard-icon">'+carIcon()+'</span><span class="dashboard-label">Veículos cadastrados</span><strong>'+Number(vehicleCount||0).toLocaleString('pt-BR')+'</strong><span class="dashboard-link">Abrir veículos →</span></button></div>')}
function cardPhotoGallery(photos,label,portrait=false,total=photos?.length||0){if(!photos?.length)return '';const coverIndex=photos.findIndex(photo=>photo.is_cover),cover=photos[coverIndex>=0?coverIndex:0],ordered=coverIndex>0?[cover,...photos.filter((_,index)=>index!==coverIndex)]:photos,shown=ordered.slice(1,6);return '<div class="card-photo-gallery '+(portrait?'portrait-card-gallery':'')+'"><div class="card-photo-cover"><img src="'+esc(cover.url)+'" alt="'+esc(label)+'" loading="lazy" decoding="async" fetchpriority="low" style="'+esc(photoStyle(cover.crop_position,portrait))+'"></div>'+(shown.length?'<div class="card-photo-thumbnails" aria-label="Até cinco miniaturas de '+esc(label)+'">'+shown.map((photo,index)=>'<span class="card-photo-thumbnail"><img src="'+esc(photo.url)+'" alt="'+esc(label)+' miniatura '+(index+1)+'" loading="lazy" decoding="async" fetchpriority="low" style="'+esc(photoStyle(photo.crop_position,portrait))+'"></span>').join('')+'</div>':'')+(total>6?'<div class="card-photo-more">Mais '+(total-6)+' foto(s)</div>':'')+'</div>'}
function personCard(p){const fallback=esc(String(p.full_name||'?').split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase()),photos=p.photos?.length?p.photos:p.photo_url?[{url:p.photo_url,is_cover:true,crop_position:p.photo_position||'50% 20%'}]:[],gallery=photos.length?cardPhotoGallery(photos,'Foto de '+(p.full_name||'indivíduo'),true,p.photo_count||photos.length):'<div class="avatar">'+fallback+'</div>';return '<article class="person-card" data-open-person="'+p.id+'" tabindex="0" role="button" aria-label="Abrir cadastro de '+esc(p.full_name)+'">'+gallery+'<h3>'+esc(p.full_name)+'</h3><div class="card-meta">CPF: '+esc(p.cpf_digits?formatCpf(p.cpf_digits):'—')+'</div><div class="card-meta">RG: '+esc(p.rg||'—')+'</div></article>'}
function personIcon(){return '<svg class="menu-svg" viewBox="0 0 24 24" aria-hidden="true"><path d="M12 12a4.2 4.2 0 1 0 0-8.4 4.2 4.2 0 0 0 0 8.4Zm0 2c-4.4 0-8 2.4-8 5.4V22h16v-2.6c0-3-3.6-5.4-8-5.4Z"/></svg>'}
function carIcon(){return '<svg class="car-icon" viewBox="0 0 64 40" aria-hidden="true"><path d="M11 25 16 12c1-3 4-5 7-5h18c3 0 6 2 7 5l5 13 4 3v8h-5a7 7 0 0 1-14 0H26a7 7 0 0 1-14 0H7v-8l4-3Zm8-2h27l-3-9c-.4-1-1-2-2-2H23c-1 0-2 1-2 2l-2 9Zm0 12a3 3 0 1 0 6 0 3 3 0 0 0-6 0Zm25 0a3 3 0 1 0 6 0 3 3 0 0 0-6 0Z"/></svg>'}function vehicleRow(v){const photos=v.photos?.length?v.photos:v.photo_url?[{url:v.photo_url,is_cover:true,crop_position:v.photo_position||'50% 50%'}]:[];return '<article class="vehicle-card" data-open-vehicle="'+v.id+'" tabindex="0" role="button" aria-label="Abrir veículo '+esc(v.plate)+'">'+(photos.length?cardPhotoGallery(photos,'Foto do veículo',false,v.photo_count||photos.length):'<div class="vehicle-placeholder">'+carIcon()+'</div>')+'<div class="vehicle-card-copy"><h3>'+esc(v.plate)+'</h3><p>'+esc([v.make,v.model,v.color].filter(Boolean).join(' · ')||'Sem marca, modelo ou cor informados')+'</p></div></article>'}
function searchBox(placeholder){return '<div class="search-control"><input class="search" id="search" type="search" placeholder="⌕  '+placeholder+'" value="'+esc(state.searchInput)+'" autocomplete="off" aria-label="Pesquisar cadastro"><button class="button search-button" id="searchButton" type="button" aria-label="Pesquisar" title="Pesquisar">⌕</button></div><p class="search-hint" id="searchHint" role="status" aria-live="polite">'+(state.searchLoading?'Buscando…':state.searchInput&&!isUsefulSearch(state.searchInput)?'Digite ao menos 3 caracteres úteis.':'')+'</p>'}
function alphabetBar(){return '<nav class="alphabet-filter" aria-label="Filtrar indivíduos por letra"><button class="'+(state.letter==='all'?'active':'')+'" data-letter="all">Todos</button>'+Array.from('ABCDEFGHIJKLMNOPQRSTUVWXYZ').map(letter=>'<button class="'+(state.letter===letter?'active':'')+'" data-letter="'+letter+'">'+letter+'</button>').join('')+'</nav>'}
function pageSizeControl(pageSize){const sizes=[30,50,100];return '<label class="page-size-control"><span>Por página</span><select class="page-select" id="pageSize" aria-label="Cadastros por página">'+sizes.map(size=>'<option value="'+size+'" '+(pageSize===size?'selected':'')+'>'+size+'</option>').join('')+'</select></label>'}
function paginationMarkup(total,page,pageSize){const pages=Math.max(1,Math.ceil(total/pageSize));return '<div class="pagination-controls"><div class="pagination"><button class="button secondary small" data-list-page="'+(page-1)+'" '+(page===0?'disabled':'')+'>← Anterior</button><label class="page-jump-control"><span>Página</span><select class="page-select" id="pageJump" aria-label="Ir para página">'+Array.from({length:pages},(_,index)=>'<option value="'+(index+1)+'" '+(page===index?'selected':'')+'>'+(index+1)+'</option>').join('')+'</select><span>de '+pages+'</span></label><button class="button secondary small" data-list-page="'+(page+1)+'" '+(page>=pages-1?'disabled':'')+'>Próxima →</button></div></div>'}
async function loadRecordCovers(entity,records){if(!records.length)return;const {data,error}=await state.client.from('record_photos').select('entity_id,photo_path,crop_position,is_cover,created_at').eq('entity',entity).in('entity_id',records.map(record=>record.id)).order('created_at',{ascending:true});if(error)throw error;const covers=new Map();for(const photo of data||[]){const current=covers.get(photo.entity_id);if(!current||photo.is_cover)covers.set(photo.entity_id,photo)}await Promise.all(records.map(async record=>{const photo=covers.get(record.id),path=photo?.photo_path||record.photo_path;record.photo_url=path?await signedPhoto(path):'';record.photo_position=photo?.crop_position||record.photo_position||'50% 50%'}))}
function hydrateCardGalleries(entity,records){if(!records.length)return;const people=entity==='people',selector=people?'[data-open-person]':'[data-open-vehicle]',render=people?personCard:vehicleRow,key=people?'openPerson':'openVehicle',byId=new Map(records.map(record=>[String(record.id),record]));const hydrate=async(card,record)=>{if(!card.isConnected||card.dataset.galleryLoading==='true')return;card.dataset.galleryLoading='true';try{await galleryPhotosForRecords(entity,[record]);if(!card.isConnected)return;const template=document.createElement('template');template.innerHTML=render(record);const replacement=template.content.firstElementChild;if(replacement){replacement.dataset.galleryLoaded='true';card.replaceWith(replacement)}}catch(error){delete card.dataset.galleryLoading;console.warn('Não foi possível carregar a galeria deste cartão.',error)}};const cards=[...document.querySelectorAll(selector)].filter(card=>byId.has(card.dataset[key])&&card.dataset.galleryLoaded!=='true');if(!('IntersectionObserver'in window)){void Promise.all(cards.map(card=>hydrate(card,byId.get(card.dataset[key]))));return}const observer=new IntersectionObserver(entries=>{for(const entry of entries){if(!entry.isIntersecting)continue;observer.unobserve(entry.target);void hydrate(entry.target,byId.get(entry.target.dataset[key]))}},{rootMargin:'320px 0px',threshold:0.01});for(const card of cards)observer.observe(card)}
async function renderRecords(){const people=state.page==='people',source=(people?state.people:state.vehicles).slice();const cmp=new Intl.Collator('pt-BR',{sensitivity:'base',numeric:true});source.sort((a,b)=>cmp.compare(people?a.full_name||'':a.plate||'',people?b.full_name||'':b.plate||''));let filtered=source;if(people&&state.letter!=='all'&&!state.serverPaged)filtered=source.filter(p=>foldName(p.full_name).startsWith(state.letter));const total=state.serverPaged?state.listTotal:filtered.length;const pages=Math.max(1,Math.ceil(total/state.listPageSize));state.listPage=Math.min(state.listPage,pages-1);const start=state.listPage*state.listPageSize,visible=state.serverPaged?source:filtered.slice(start,start+state.listPageSize);if(visible.length)await loadRecordCovers(people?'people':'vehicles',visible);const relatedRecords=isUsefulSearch(state.query)?(people?state.vehicles.slice(0,8):state.people.slice(0,8)):[];if(relatedRecords.length)await loadRecordCovers(people?'vehicles':'people',relatedRecords);const related=isUsefulSearch(state.query)?people?'<div class="section-heading"><h2>Veículos relacionados ('+state.vehicles.length+')</h2></div><div class="cards vehicle-cards">'+(relatedRecords.length?relatedRecords.map(vehicleRow).join(''):'<div class="empty">Nenhum veículo encontrado para esta pesquisa.</div>')+'</div>':'<div class="section-heading"><h2>Pessoas encontradas ('+state.people.length+')</h2></div><div class="cards individual-cards">'+(relatedRecords.length?relatedRecords.map(personCard).join(''):'<div class="empty">Nenhuma pessoa encontrada.</div>')+'</div>':'';const subtitle=people?'Pesquise e filtre os indivíduos por nome, CPF, RG ou endereço.':'Pesquise veículos por placa, modelo, pessoa ou endereço.';const records='<div class="cards '+(people?'individual-cards':'vehicle-cards')+'">'+(visible.length?visible.map(people?personCard:vehicleRow).join(''):'<div class="empty">'+(state.query.length>0&&!isUsefulSearch(state.query)?'Digite ao menos 3 caracteres úteis.':people?'Nenhum indivíduo encontrado nesta letra.':'Nenhum veículo encontrado.')+'</div>')+'</div>';const searchElement=$('#search'),restoreSearchFocus=!!searchElement&&document.activeElement===searchElement,searchCursor=restoreSearchFocus?{start:searchElement.selectionStart,end:searchElement.selectionEnd,direction:searchElement.selectionDirection}:null;frame('<div class="page-intro"><div><h1>'+(people?'Indivíduos':'Veículos')+'</h1><p>'+subtitle+'</p></div><button class="button" data-add="'+(people?'person':'vehicle')+'">＋ Adicionar</button></div>'+searchBox(people?'Buscar indivíduo, endereço, CPF ou placa':'Buscar placa, modelo, pessoa, CPF ou endereço')+(people?'<div class="alphabet-toolbar">'+alphabetBar()+pageSizeControl(state.listPageSize)+'</div>':pageSizeControl(state.listPageSize))+(isUsefulSearch(state.query)?'<h2 class="result-heading">'+(people?'Indivíduos':'Veículos')+' encontrados ('+filtered.length+')</h2>':'')+records+paginationMarkup(total,state.listPage,state.listPageSize)+related  );if(searchCursor){const restored=$('#search');if(restored){restored.focus({preventScroll:true});restored.setSelectionRange(searchCursor.start,searchCursor.end,searchCursor.direction)}}wireSearch();wireCarousels();void Promise.all([hydrateCardGalleries(people?'people':'vehicles',visible),hydrateCardGalleries(people?'vehicles':'people',relatedRecords)])}
function foldName(value){return String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleUpperCase('pt-BR')}
function formatCpf(cpf){const d=String(cpf||'').replace(/\D/g,'');return d.length===11?d.slice(0,3)+'.'+d.slice(3,6)+'.'+d.slice(6,9)+'-'+d.slice(9):d}
function wireSearch(){const input=$('#search'),button=$('#searchButton');if(!input)return;const run=async(force=false)=>{state.searchInput=input.value;state.query=input.value.trim();state.listPage=0;state.letter='all';const key=state.page+'|'+state.query;const request=++state.searchRequest;state.searchLoading=true;const hint=$('#searchHint');if(hint)hint.textContent=state.query&&!isUsefulSearch(state.query)?'Digite ao menos 3 caracteres úteis.':state.query?'Buscando…':'';if(state.query&&!isUsefulSearch(state.query)){state.lastSearchKey=key;state.searchLoading=false;state.serverPaged=false;state.listTotal=0;state.people=[];state.vehicles=[];await renderRecords();return}if(!force&&key===state.lastSearchKey){state.searchLoading=false;return}if(button)button.disabled=true;try{await loadRecords(request);if(request!==state.searchRequest)return;state.lastSearchKey=key;await renderRecords()}catch(error){if(request===state.searchRequest){state.searchLoading=false;const status=$('#searchHint');if(status)status.textContent='Não foi possível concluir a pesquisa. Tente novamente.';toast(msg(error))}}finally{if(request===state.searchRequest){state.searchLoading=false;const active=$('#searchButton');if(active)active.disabled=false;const status=$('#searchHint');if(status)status.textContent=state.query&&!isUsefulSearch(state.query)?'Digite ao menos 3 caracteres úteis.':state.query?'Pesquisa concluída.':''}}};input.addEventListener('input',()=>{state.searchInput=input.value;clearTimeout(state.searchTimer);state.searchTimer=setTimeout(()=>void run(false),500)});input.addEventListener('keydown',event=>{if(event.key==='Enter'){event.preventDefault();clearTimeout(state.searchTimer);void run(true)}});button?.addEventListener('click',()=>{clearTimeout(state.searchTimer);void run(true)})}
async function pdfPhotoData(photo,index){const response=await fetch(photo.url,{mode:'cors',credentials:'omit'});if(!response.ok)throw new Error('Não foi possível carregar a foto '+(index+1)+' para o PDF.');const bitmap=await createImageBitmap(await response.blob());const ratio=Math.min(1,1600/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*ratio));canvas.height=Math.max(1,Math.round(bitmap.height*ratio));canvas.getContext('2d',{alpha:false}).drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close?.();const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',0.88));if(!blob)throw new Error('Não foi possível preparar uma foto para o PDF.');return{bytes:new Uint8Array(await blob.arrayBuffer()),width:canvas.width,height:canvas.height,is_cover:Boolean(photo.is_cover),label:photo.is_cover?'Foto de capa':'Fotografia '+(index+1)}}
function downloadPdf(blob,filename){const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=filename;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),60000)}
function renderPdfPrintPreview(container,pages){
 container.replaceChildren();
 pages.slice(0,1).forEach((page,pageIndex)=>{
  const canvas=document.createElement('canvas');
  canvas.className='pdf-print-page';
  canvas.width=1190;canvas.height=1684;
  canvas.setAttribute('role','img');
  canvas.setAttribute('aria-label','Prévia completa da folha A4, página '+(pageIndex+1));
  container.append(canvas);
  const context=canvas.getContext('2d',{alpha:false});
  if(!context)return;
  context.fillStyle='#fff';context.fillRect(0,0,595,842);context.scale(2,2);
  const imageLoads=page.images.map(item=>new Promise(resolve=>{
   const photo=item.photo;
   if(!photo?.bytes){resolve(null);return}
   const url=URL.createObjectURL(new Blob([photo.bytes],{type:'image/jpeg'})),image=new Image();
   image.onload=()=>resolve({image,item,url});
   image.onerror=()=>{URL.revokeObjectURL(url);resolve(null)};
   image.src=url;
  }));
  Promise.all(imageLoads).then(loaded=>{
   for(const result of loaded){if(result)context.drawImage(result.image,result.item.x,842-result.item.y-result.item.height,result.item.width,result.item.height)}
   for(const item of page.texts){
    context.fillStyle='rgb('+item.color.map(value=>Math.round(Math.max(0,Math.min(1,value))*255)).join(',')+')';
    context.font=item.size+'px Arial, Helvetica, sans-serif';context.textBaseline='alphabetic';
    context.fillText(item.text,item.x,842-item.y)
   }
   for(const result of loaded)if(result)URL.revokeObjectURL(result.url)
  })
 })
}
function openPdfShareDialog(blob,filename,title,previewPages=[]){const url=URL.createObjectURL(blob),dialog=document.createElement('dialog');dialog.className='pdf-share-dialog';dialog.innerHTML='<div class="pdf-share-content"><div class="dialog-head"><div><h2>PDF pronto para compartilhar</h2><p>Prévia da primeira folha A4. O PDF completo tem '+previewPages.length+' '+(previewPages.length===1?'página.':'páginas.')+'</p></div><button type="button" class="close" data-pdf-close aria-label="Fechar">×</button></div><div class="pdf-preview-pages" data-pdf-preview aria-label="Prévia do documento"></div><div class="dialog-actions"><button type="button" class="button" data-pdf-share>Compartilhar PDF</button></div></div>';document.body.append(dialog);dialog.querySelector('[data-pdf-close]').addEventListener('click',()=>dialog.close());dialog.querySelector('[data-pdf-share]').addEventListener('click',async()=>{const file=new File([blob],filename,{type:'application/pdf'});try{if(navigator.share&&navigator.canShare?.({files:[file]})){await navigator.share({files:[file],title,text:'Ficha do Cadastro Criminal: '+title});return}downloadPdf(blob,filename);toast('PDF baixado. Anexe-o à conversa do WhatsApp.')}catch(error){if(error.name==='AbortError')return;downloadPdf(blob,filename);toast('PDF baixado para você enviar pelo WhatsApp.')}});dialog.addEventListener('close',()=>{URL.revokeObjectURL(url);dialog.remove()},{once:true});dialog.showModal();requestAnimationFrame(()=>{if(dialog.open)renderPdfPrintPreview(dialog.querySelector('[data-pdf-preview]'),previewPages.slice(0,1))})}
async function generateRecordPdf(entity,id){try{const table=entity==='people'?'people':'vehicles';const {data:record,error}=await state.client.from(table).select('*').eq('id',id).single();if(error)throw error;if(!record)throw new Error('Cadastro não encontrado.');const photos=await galleryPhotos(entity,record),embeddedPhotos=await Promise.all(photos.map(pdfPhotoData));let rows;if(entity==='people'){const addresses=[record.address_primary,record.address_secondary,...(Array.isArray(record.additional_addresses)?record.additional_addresses:[])].filter(Boolean);rows=[['Nome completo',record.full_name],['CPF',record.cpf_digits?formatCpf(record.cpf_digits):''],['RG',record.rg],['Matrícula',record.registration],['Apelido/Vulgo',record.alias],['Nascimento',record.birthday?new Date(record.birthday+'T00:00:00').toLocaleDateString('pt-BR'):''],['Endereços',addresses.join('\n')],['Anotações',record.notes],['Crimes',[record.occurrence_notes,record.occurrence_reference].filter(Boolean).join('\n')],['Características',record.characteristics],['Criado em',record.created_at?new Date(record.created_at).toLocaleString('pt-BR'):''],['Atualizado em',record.updated_at?new Date(record.updated_at).toLocaleString('pt-BR'):'']]}else{rows=[['Placa',record.plate],['Marca',record.make],['Modelo',record.model],['Cor',record.color],['Ano de fabricação',record.fabrication_year],['Ano do modelo',record.model_year],['Anotações',record.notes],['Criado em',record.created_at?new Date(record.created_at).toLocaleString('pt-BR'):''],['Atualizado em',record.updated_at?new Date(record.updated_at).toLocaleString('pt-BR'):'']]};const title=entity==='people'?'Ficha do indivíduo':'Ficha do veículo',recordName=entity==='people'?record.full_name:record.plate;const sections=[{title:entity==='people'?'Identificação e informações do indivíduo':'Informações do veículo',rows:rows.filter(([,value])=>value!==null&&value!==undefined&&String(value).trim()!=='').map(([label,value])=>({label,value}))}];const bytes=buildRecordPdf({title,recordName,sections,photos:embeddedPhotos});const filename=((entity==='people'?record.full_name:record.plate)||'Cadastro').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^A-Za-z0-9_-]+/g,'-')+'.pdf';openPdfShareDialog(new Blob([bytes],{type:'application/pdf'}),filename,title+' — '+recordName,bytes.previewPages||[])}catch(error){toast('Não foi possível gerar o PDF: '+msg(error))}}
async function showLinkForm(entity,id){const isPerson=entity==='person',labelKey=isPerson?'plate':'full_name';let options;try{options=await loadAllActive(isPerson?'vehicles':'people',isPerson?'plate':'full_name')}catch(error){toast(msg(error));return}const d=$('#recordDialog'),targetField=isPerson?'<div class="field full"><label for="vehicleAssociationSearch">Pesquisar veículo pela placa</label><input id="vehicleAssociationSearch" type="search" autocomplete="off" placeholder="Digite a placa (AAA0000 ou AAA0A00)"><input id="linkTarget" name="target" type="hidden"><div id="vehicleAssociationResults" class="association-search-results" role="listbox"></div><button class="button secondary small association-search-create" type="button" data-create-associated-vehicle>＋ Cadastrar veículo</button></div>':'<div class="field full"><label for="linkTarget">Pessoa</label><select id="linkTarget" name="target" required><option value="">Selecione</option>'+options.map(x=>'<option value="'+esc(x.id)+'">'+esc(x[labelKey])+'</option>').join('')+'</select></div>';d.innerHTML='<div class="dialog-inner"><div class="dialog-head"><h2>Associar '+(isPerson?'veículo à pessoa':'pessoa ao veículo')+'</h2><button class="close" data-close>×</button></div><form id="linkForm"><div class="form-grid">'+targetField+'<div class="field"><label for="relation">Relação</label><select id="relation" name="relation"><option value="driver">Condutor</option><option value="owner">Proprietário</option><option value="associated">Associado</option></select></div>'+field('Notas do vínculo','notes','','text',true)+'</div></form><div class="dialog-actions"><button class="button secondary" data-close type="button">Cancelar</button><button class="button" type="submit" form="linkForm">Associar</button></div></div>';d.showModal();if(isPerson){const search=d.querySelector('#vehicleAssociationSearch'),target=d.querySelector('#linkTarget'),results=d.querySelector('#vehicleAssociationResults'),renderResults=()=>{const plate=search.value.toUpperCase().replace(/[^A-Z0-9]/g,'').slice(0,7);if(!plate){results.innerHTML='<div class="association-search-hint">Digite uma placa para pesquisar.</div>';return}if(plate.length<7){results.innerHTML='<div class="association-search-hint">A placa deve conter 7 caracteres: AAA0000 ou AAA0A00.</div>';return}if(!/^(?:[A-Z]{3}[0-9]{4}|[A-Z]{3}[0-9][A-Z][0-9]{2})$/.test(plate)){results.innerHTML='<div class="association-search-empty" role="alert">Placa inválida. Use o padrão AAA0000 ou AAA0A00.</div>';return}const matches=options.filter(v=>String(v.plate||'').toUpperCase().replace(/[^A-Z0-9]/g,'')===plate).slice(0,12);if(matches.length){results.innerHTML=matches.map(v=>'<button class="association-search-option" type="button" role="option" data-association-vehicle="'+esc(v.id)+'"><strong>'+esc(v.plate)+'</strong><span>'+esc([v.make,v.model,v.color].filter(Boolean).join(' · '))+'</span></button>').join('');return}results.innerHTML='<div class="association-search-empty">Nenhum veículo encontrado com esta placa. Você ainda pode cadastrar.</div>'};search.addEventListener('input',()=>{search.value=search.value.toUpperCase().replace(/[^A-Z0-9]/g,'').slice(0,7);target.value='';renderResults()});results.addEventListener('click',event=>{const choice=event.target.closest('[data-association-vehicle]');if(choice){const vehicle=options.find(v=>v.id===choice.dataset.associationVehicle);if(!vehicle)return;target.value=vehicle.id;search.value=[vehicle.plate,vehicle.make,vehicle.model].filter(Boolean).join(' · ');results.innerHTML='<div class="association-search-selected"><span>Selecionado: <strong>'+esc(search.value)+'</strong></span><button class="button secondary small" type="button" data-clear-associated-vehicle>Trocar</button></div>';return}if(event.target.closest('[data-clear-associated-vehicle]')){target.value='';search.value='';renderResults();search.focus();return}});d.querySelector('[data-create-associated-vehicle]')?.addEventListener('click',()=>{if(target.value){toast('O veículo já está selecionado. Clique em Associar para criar o vínculo sem alterar os demais.');return}const plate=search.value.toUpperCase().replace(/[^A-Z0-9]/g,'');if(!/^(?:[A-Z]{3}[0-9]{4}|[A-Z]{3}[0-9][A-Z][0-9]{2})$/.test(plate)){results.innerHTML='<div class="association-search-empty" role="alert">Placa inválida. Informe 7 caracteres no padrão AAA0000 ou AAA0A00.</div>';toast('A placa deve seguir o padrão AAA0000 ou AAA0A00.');search.focus();return}const relation=d.querySelector('#relation')?.value||'driver';d.close();void showForm('vehicle',null,{initialPersonId:id,initialRelation:relation,initialPlate:plate})});renderResults()}$('#linkForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget),target=f.get('target');if(!target){toast(isPerson?'Pesquise e selecione um veículo ou cadastre um novo.':'Selecione uma pessoa.');if(isPerson)d.querySelector('#vehicleAssociationSearch')?.focus();else d.querySelector('#linkTarget')?.focus();return}const values={person_id:isPerson?id:target,vehicle_id:isPerson?target:id,relation:f.get('relation'),notes:f.get('notes'),created_by:state.session.user.id};const {error}=await state.client.from('person_vehicle_links').insert(values);if(error){toast(msg(error));return}d.close();toast('Associação registrada.');if(isPerson)await openPerson(id);else await openVehicle(id)}}
async function archiveRecord(table,id){if(!confirm('Arquivar este cadastro? Ele deixará de aparecer nas pesquisas, mas poderá ser restaurado pelo histórico.'))return;const {error}=await state.client.from(table).update({archived_at:new Date().toISOString(),updated_by:state.session.user.id}).eq('id',id);if(error){toast(msg(error));return}toast('Cadastro arquivado.');state.selected=null;await loadPage()}
async function deleteRecord(entity,id){if(!isAdmin())return;if(!confirm('Excluir permanentemente este cadastro e suas associações? Esta ação não pode ser desfeita.'))return;const {data:photos}=await state.client.from('record_photos').select('photo_path').eq('entity',entity).eq('entity_id',id);const {data:record}=await state.client.from(entity).select('photo_path').eq('id',id).maybeSingle();const paths=[...(photos||[]).map(photo=>photo.photo_path),record?.photo_path].filter(Boolean);const {error}=await state.client.rpc('admin_delete_record',{target_entity:entity,target_record_id:id});if(error){toast(msg(error));return}if(paths.length){const result=await removeUnreferencedPhotoFiles(paths);if(result.error)toast('Cadastro excluído; alguns arquivos foram mantidos porque não foi possível verificar se pertencem a outro registro.');else if(result.kept)toast('Cadastro excluído; fotos ainda vinculadas a outros registros foram preservadas.')}await clearPhotoCache(state.session.user.id);toast('Cadastro excluído.');state.selected=null;await loadPage()}
async function dedupePeoplePhotos(){if(!isAdmin())return;const button=$('#dedupePeoplePhotos');if(button)button.disabled=true;try{const {data:preview,error:previewError}=await state.client.functions.invoke('dedupe-person-photos',{body:{dryRun:true}});if(previewError)throw previewError;if(!preview?.duplicateReferences){toast('Nenhuma foto duplicada foi encontrada.');return}const message='A verificação encontrou '+Number(preview.duplicateReferences).toLocaleString('pt-BR')+' referências repetidas em '+Number(preview.affectedPeople).toLocaleString('pt-BR')+' cadastros. O sistema mantém a foto de capa e uma cópia de cada imagem. Posso remover as duplicatas agora?';if(!confirm(message))return;const {data,error:resultError}=await state.client.functions.invoke('dedupe-person-photos',{body:{dryRun:false}});if(resultError)throw resultError;if(!data?.ok){toast(data?.error||'A limpeza terminou parcialmente. Verifique e tente novamente.');return}toast('Limpeza concluída: '+Number(data.duplicateReferencesRemoved||0).toLocaleString('pt-BR')+' referências removidas e '+Number(data.duplicateFilesDeleted||0).toLocaleString('pt-BR')+' arquivos duplicados excluídos.');await renderTeam()}catch(error){toast(msg(error))}finally{const active=$('#dedupePeoplePhotos');if(active)active.disabled=false}}
